using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
[InitializeOnLoad]
public static class AttackMotionDiagnostics
{
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;static bool started;static double deadline;
 static string Folder=>Path.Combine(Path.GetDirectoryName(Application.dataPath),"Temp/TCardAttackMotionValidation");
 static AttackMotionDiagnostics(){EditorApplication.update+=Tick;}
 [MenuItem("Tools/T-card/Validate Attack Motion (Play)")]static void Begin(){AttackMotionSettingsEditor.Ensure();SessionState.SetBool("TCardMotionProbe",true);started=false;deadline=EditorApplication.timeSinceStartup+180;EditorApplication.isPlaying=true;}
 static void Tick(){if(!SessionState.GetBool("TCardMotionProbe",false)||started||!EditorApplication.isPlaying||EditorApplication.isCompiling)return;if(deadline==0)deadline=EditorApplication.timeSinceStartup+180;if(EditorApplication.timeSinceStartup>deadline){Finish("FAIL: timeout");return;}var d=UnityEngine.Object.FindFirstObjectByType<HandDealer>();if(d!=null&&d.IsOpeningDecisionReady){started=true;d.StartCoroutine(Probe(d));}}
 static void Finish(string s){Directory.CreateDirectory(Folder);File.WriteAllText(Path.Combine(Folder,"result.txt"),s);Debug.Log(s);SessionState.SetBool("TCardMotionProbe",false);EditorApplication.isPlaying=false;}
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 static CardController Add(HandDealer d,Transform parent,string rank){var go=UnityEngine.Object.Instantiate(d.proHandCardPrefab,parent);var c=go.GetComponent<CardController>();c.SetData(AssetDatabase.LoadAssetAtPath<CardData>("Assets/CardData/Spade_"+rank+".asset"));c.SetSummonSickness(false);return c;}
 static IEnumerator Run(IEnumerator routine,Action done){yield return routine;done();}
 static void Capture(string name){var im=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(Path.Combine(Folder,name+".png"),im.EncodeToPNG());UnityEngine.Object.Destroy(im);}
 static IEnumerator Probe(HandDealer d)
 {
  Directory.CreateDirectory(Folder);var t=d.turnManager;d.turnManager=null;typeof(HandDealer).GetMethod("CompleteOpeningSelection",Flags).Invoke(d,null);d.turnManager=t;typeof(TurnManager).GetField("inactivityTimersEnabled",Flags).SetValue(t,false);yield return new WaitForSeconds(.4f);
  var s=AttackMotionSettings.Load();
  try{Check(Mathf.Abs(AttackMotionPresentation.Pose(s,.5f,1).x-s.liftDistance)<.01f,"Anticipation moved forward early");Check(Mathf.Abs(AttackMotionPresentation.Pose(s,s.ImpactTime,1).y-s.floatingScale*s.lungeZoom)<.001f,"Extra lunge zoom missing");Check(AttackMotionPresentation.DefenderPose(s,.4f,1).y>1,"Defender float missing");Check(AttackMotionPresentation.DefenderPose(s,s.ImpactTime,1).x<0&&AttackMotionPresentation.DefenderPose(s,s.ImpactTime,-1).x>0,"Defender direction incorrect");Check(AttackMotionPresentation.DefenderPose(s,s.Duration,1).x==0,"Defender did not return");Check(!ShaderUtil.ShaderHasError(Shader.Find("T-card/UI/Attack Motion Focus")),"Motion lowlight shader error");Check(AttackMotionPresentation.Pose(s,s.Duration,1).x==0,"Pose not restored");}catch(Exception e){Finish("FAIL: "+e);yield break;}
  foreach(string mode in new[]{"win","lose","tie","enemy","walls","wall-single","enemy-walls"}){
   bool enemy=mode=="enemy"||mode=="enemy-walls";bool wallsMode=mode=="walls"||mode=="wall-single"||mode=="enemy-walls";int wallTargets=mode=="wall-single"?1:2;var a=Add(d,enemy?t.enemyBattleArea:t.playerBattleArea,mode=="lose"?"2":wallsMode&&wallTargets==2?"K":"10");var b=Add(d,enemy?t.playerBattleArea:t.enemyBattleArea,mode=="lose"?"K":mode=="tie"?"10":"3");a.Tap();yield return new WaitForSeconds(.3f);
   var before=a.transform.localPosition;var scale=a.transform.localScale;var group=a.GetComponent<CanvasGroup>()??a.gameObject.AddComponent<CanvasGroup>();float alpha=group.alpha;var defenderBefore=b.transform.localPosition;var defenderScale=b.transform.localScale;var defenderGroup=b.GetComponent<CanvasGroup>()??b.gameObject.AddComponent<CanvasGroup>();float defenderAlpha=defenderGroup.alpha;bool focusCaptured=false;bool done=false,captured=false,checkedHold=false,checkedImpact=false;string error=null;
   var victims=new List<CardController>();
   IEnumerator routine;
   if(wallsMode){var zone=enemy?d.wallArea:d.enemyWallArea;foreach(Transform child in zone){var c=child.GetComponent<CardController>();if(c!=null&&c.data!=null)victims.Add(c);if(victims.Count==wallTargets)break;}routine=t.PlayAttackMotion(a,victims,victims,zone);}else routine=t.PlayAttackBattleMotion(a,b);
   d.StartCoroutine(Run(routine,()=>done=true));float until=Time.realtimeSinceStartup+10;
   while(!done&&Time.realtimeSinceStartup<until){var fx=t.GetComponent<AttackMotionPresentation>();try{if(fx!=null&&fx.MovingCard!=null){Check(!t.CanDragPlayerHand,"Hand input active during attack");Check(Mathf.Abs(group.alpha)<.001f,"Original card remains visible");Check(Vector3.Distance(a.transform.localPosition,before)<.1f&&Vector3.Distance(a.transform.localScale,scale)<.01f,"Gameplay card transform moved");if(fx.Elapsed>=s.liftDuration&&fx.Elapsed<s.liftDuration+s.anticipationDuration){checkedHold=true;Check(fx.FocusGraphic!=null&&fx.FocusGraphic.Opacity>.99f&&fx.FocusGraphic.EntryCount==(wallsMode?2+wallTargets:2),"Execution lowlight not active");Check(Mathf.Abs(fx.FocusGraphic.material.GetColor("_DimColor").a-s.lowlightColor.a)<.001f,"Lowlight strength not applied");if(wallsMode){var entries=fx.FocusGraphic.material.GetVectorArray("_Entries");var glows=fx.FocusGraphic.material.GetVectorArray("_Colors");for(int i=0;i<wallTargets;i++){var color=glows[2+i];Check(Vector3.Distance(new Vector3(color.x,color.y,color.z),new Vector3(s.wallTargetColor.r,s.wallTargetColor.g,s.wallTargetColor.b))<.001f&&Mathf.Abs(color.w-s.wallTargetGlow*s.wallTargetColor.a)<.001f,"Selected wall red glow missing");var rt=victims[i].artworkImage.rectTransform;var corners=new Vector3[4];rt.GetWorldCorners(corners);var center=RectTransformUtility.WorldToScreenPoint(null,(corners[0]+corners[2])*.5f);Check(Vector2.Distance(new Vector2(entries[2+i].x,entries[2+i].y),center)<1f,"Wall outline does not follow selected target");}var feathers=fx.FocusGraphic.material.GetVectorArray("_Flags");var tune=fx.FocusGraphic.material.GetVector("_WallTune");float unit=Screen.width/720f;Check(feathers[1].z==1&&feathers[2].z==0&&Mathf.Abs(tune.x-s.wallZoneCornerRadius*unit)<.01f&&Mathf.Abs(tune.y-s.wallZoneGlowBlur*unit)<.01f,"Wall-specific corner/blur configuration missing");Check(feathers[1].x==s.wallLowlightFeather&&feathers[1].x>s.cardLowlightFeather,"Wall feather not stronger");}else{Check(fx.DefendingCard!=null&&defenderGroup.alpha==0,"Battle target proxy missing");Check(Vector3.Distance(b.transform.localPosition,defenderBefore)<.1f&&b.transform.localScale==defenderScale,"Defender gameplay transform moved");}}if(fx.ImpactEmitted){checkedImpact=true;Check(fx.VictimCount==(wallsMode?wallTargets:mode=="tie"?2:1),"Incorrect impact victim count");}}}catch(Exception e){error=e.ToString();break;}
    if(!focusCaptured&&fx!=null&&fx.MovingCard!=null&&fx.Elapsed>.38f&&fx.Elapsed<.54f){yield return new WaitForEndOfFrame();Capture(mode+"-focus");
     if(mode=="win"){var lit=ScreenCapture.CaptureScreenshotAsTexture();float beforeDim=lit.GetPixel(45,Screen.height/2).grayscale;UnityEngine.Object.Destroy(lit);fx.FocusGraphic.gameObject.SetActive(false);yield return null;yield return new WaitForEndOfFrame();var plain=ScreenCapture.CaptureScreenshotAsTexture();float withoutDim=plain.GetPixel(45,Screen.height/2).grayscale;UnityEngine.Object.Destroy(plain);fx.FocusGraphic.gameObject.SetActive(true);File.WriteAllText(Path.Combine(Folder,"lowlight.txt"),"Pixel luminance: focused="+beforeDim+", plain="+withoutDim+", ratio="+(beforeDim/withoutDim));if(beforeDim>=withoutDim*.55f){Finish("FAIL: Execution lowlight is not visibly dark enough");yield break;}}
     focusCaptured=true;}
    if(!captured&&fx!=null&&fx.MovingCard!=null&&fx.ImpactEmitted&&fx.Elapsed>s.ImpactTime+.12f){yield return new WaitForEndOfFrame();Capture(mode);var impactGraphic=UnityEngine.Object.FindFirstObjectByType<AttackImpactGraphic>();File.AppendAllText(Path.Combine(Folder,"mesh.txt"),mode+" age="+impactGraphic.Age+" vertices="+impactGraphic.VertexCount+" rect="+impactGraphic.rectTransform.rect+"\\n");captured=true;}yield return null;
   }
   try{Check(done&&error==null,error??"Animation did not finish");Check(checkedHold&&checkedImpact&&captured,"Phases missing");Check(!AttackMotionPresentation.IsPlaying&&Mathf.Approximately(group.alpha,alpha),"Visual/input state not restored");Check(a.transform.localPosition==before&&a.transform.localScale==scale,"Final transform changed");Check(b.transform.localPosition==defenderBefore&&b.transform.localScale==defenderScale&&Mathf.Approximately(defenderGroup.alpha,defenderAlpha),"Defender state not restored");if(!wallsMode){typeof(TurnManager).GetMethod("ResolveCardBattle",Flags).Invoke(t,new object[]{a,b});Check((a.transform.parent==t.playerGraveyard||a.transform.parent==t.enemyGraveyard)==(mode=="lose"||mode=="tie"),"Attacker outcome changed");Check((b.transform.parent==t.playerGraveyard||b.transform.parent==t.enemyGraveyard)==(mode!="lose"),"Defender outcome changed");}}catch(Exception e){Finish("FAIL: "+e);yield break;}
   UnityEngine.Object.Destroy(a.gameObject);UnityEngine.Object.Destroy(b.gameObject);yield return null;
  }
  Finish("PASS: real card prefabs; longer anticipation, 1.16x float and 1.07x extra lunge zoom; defender float/counter/recoil and mirrored direction; independent execution lowlight and stronger wall-zone feather; winner/loser/tie including enemy direction; selected wall red glows separate from zone, one/two targets including enemy wall attacks; two simultaneous wall impact targets; focused lowlight and hand input gate; exactly preserved gameplay transforms and restored opacity; battle results unchanged. No scene saved.");
 }
}
